def schwarzschild_radius(M):
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    return 3 * G * M / c**2

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3)*GM/c^2
    return 3 * math.sqrt(3) * G * M / c**2

def horizon_area(M):
    rs = schwarzschild_radius(M)
    return 4 * math.pi * rs**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    rs = schwarzschild_radius(M)
    area = horizon_area(M)
    l_p2 = planck_length()**2
    return area / (4 * l_p2)

def photon_sphere_impact_parameter(M):
    # For a Schwarzschild black hole the critical impact parameter equals twice the photon-sphere radius
    return 2 * photon_sphere_radius(M)

def impact_parameter_ratio(M):
    b_crit = critical_impact_parameter(M)
    b_ph = photon_sphere_impact_parameter(M)
    return b_crit / b_ph

def main():
    # Example mass: 10 solar masses
    M = 10 * M_sun

