import math

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8         # m s^-1
hbar = 1.054571817e-34    # J s
k_B = 1.380649e-23        # J K^-1
M_sun = 1.98847e30        # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # Prograde ISCO for a non-rotating BH (a=0) in geometric units (GM/c^2)
    return 6 * G * M / c**2

def photon_sphere_radius(M):
    # Critical impact parameter for photon capture (GM/c^2)
    return 3 * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def photon_sphere_impact_parameter(M):
    # In geometric units the impact parameter equals the photon sphere radius
    return 3 * G * M / c**2

def critical_impact_parameter(M):
    # Distinguish between prograde (photon sphere) and retrograde (isocenter) critical impact parameters
    return photon_sphere_impact_parameter(M)

def horizon_area(M):
    r_s = schwarzschild_radius(M)
    return 4 * math.pi * r_s**2

def entropy(M):
    r_s = schwarzschild_radius(M)
    A = horizon_area(M)
    l_p2 = planck_length()**2
    return k_B * A / (4 * l_p2)

def test():
    # Example mass: 10 solar masses
    M = 10 * M_sun
    r_s = schwarzschild_radius(M)
    r_isco = isco_radius(M)
    r_ph = photon_sphere_radius(M)
    T = hawking_temperature(M)
    l_p = planck_length()
    A = horizon_area(M)
    S = entropy(M)
    print(f"Schwarzschild radius (M=10 M_sun): {r_s:.3e} m")
    print(f"ISCO radius (non-rotating): {r_isco:.3e} m")
    print(f"Photon sphere radius: {r_ph:.3e} m")
    print(f"Hawking temperature: {T:.3e} K")
    print(f"Planck length: {l_p:.3e} m")
    print(f"Horizon area: {A:.3e} m^2")
    print(f"Bekenstein‑Hawking entropy: {S:.3e} J/K")

if __name__ == "__main__":
    test()

