    print(f"Standard Hawking temperature: {T_std:.3e} K")
    print(f"Reduced‑phase‑space temperature: {T_q:.3e} K")
    print(f"Relative error: {rel_error:.3e}")
    if rel_error < 1e-12:
        print("PASS: temperatures agree within 1e-12")
    else:
        print("FAIL: deviation exceeds threshold")

