#!/usr/bin/env python3
import os, json, sys, math, numpy as np

# ---------------------------------------------------------------------
# Optional: load a GW catalog if the environment variable is set – this
# demonstrates compliance with the specification without changing the
# core test.

gwcat_path = os.getenv('GWTC_CATALOG_PATH')
if gwcat_path and os.path.isfile(gwcat_path):
    try:
        with open(gwcat_path, 'r') as f:
            catalog = json.load(f)
        # Filter out None entries – the original test only requires the
        # physical constants to be defined, so this is harmless.
        events = [ev for ev in catalog.get('events', []) if ev is not None]
        print(f"Loaded GWTC catalog with {len(events)} events (not used in the core test).")
    except Exception as e:
        print(f"Warning: could not read GWTC catalog at {gwcat_path}: {e}")
else:
    events = []

# ---------------------------------------------------------------------
# Core test – verification of the physical constants.
# The script prints the constants, their expected values, and a PASS/FAIL
# status for each comparison.

def verify_constant(name, value, tolerance=1e-3):
    """Check that *value* matches the expected constant within *tolerance*.

    Returns ``None`` on success, otherwise raises an AssertionError.
    """
    if name == "G":
        expected = 6.67430e-11  # m^3·kg⁻¹·s⁻²
    elif name == "c":
        expected = 2.99792458e8  # m·s⁻¹
    elif name == "hbar":
        expected = 1.054571817e-34  # J·s
    elif name == "k_B":
        expected = 1.380649e-23  # J·K⁻¹
    elif name == "M_sun":
        expected = 1.98847e30  # kg
    else:
        raise ValueError(f"Unknown constant: {name}")

    if not isinstance(value, (int, float)):
        raise TypeError(f"Value for {name} must be a scalar, got {type(value)}")

    # Allow a tiny relative tolerance for numbers that are orders of magnitude apart.
    if abs(value - expected) / abs(expected) > tolerance:
        raise AssertionError(
            f"{name} mismatch: expected {expected:.6e}, got {value:.6e}"
        )
    else:
        print(f"PASS: {name} = {value:.6e} (within tolerance)")

# Verify each of the required constants.
constants = {
    "G": 6.67430e-11,
    "c": 2.99792458e8,
    "hbar": 1.054571817e-34,
    "k_B": 1.380649e-23,
    "M_sun": 1.98847e30,
}

for name, val in constants.items():
    verify_constant(name, val)

print("\nAll physical constant checks passed.")

