import os, json, math, random, statistics
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8         # m·s⁻¹
hbar = 1.054571817e-34   # J·s
k_B = 1.380649e-23       # J·K⁻¹
M_sun = 1.98847e30       # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3) * GM / c^2
    return 3 * math.sqrt(3) * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def random_event_probability(p):
    return random.random() < p

def run_trials(M, N_trials=10000, p_crit=1e-5):
    b_crit = critical_impact_parameter(M)
    hits = 0
    for _ in range(N_trials):
        if random_event_probability(p_crit):
            hits += 1
    return hits / N_trials

if __name__ == "__main__":
    masses = {
        "Sun": M_sun,
        "10 Solar masses": 10 * M_sun,
        "100 Solar masses": 100 * M_sun
    }
    print("--- Black Hole Critical Impact Parameter Test ---")
    for name, M in masses.items():
        b_crit_m = critical_impact_parameter(M)
        print(f"{name}: b_crit = {b_crit_m:.3e} m")
    print("\n--- Hawking Temperature Test ---")
    for name, M in masses.items():
        T = hawking_temperature(M)
        print(f"{name}: Hawking temperature = {T:.3e} K")
    print("\n--- Random Event Consistency Test (p = 1e-5) ---")
    for name, M in masses.items():
        prob = run_trials(M)
        print(f"{name}: measured probability ≈ {prob:.6f} (expected ~1e-5)")

#!/usr/bin/env python3
import numpy as np, sys, json, os


def load_gwtc_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if path and os.path.isfile(path):
        try:
            with open(path, 'r') as f:
                catalog = json.load(f)
            events = catalog.get('events', [])
            return [e for e in events if e.get('final_mass_source') is not None]
        except Exception as exc:
            print(f"Failed to load GWTC catalog: {exc}\nSkipping catalog load.")
    # fallback small synthetic sample
    return [
        {"final_mass_source": 10.2},
        {"final_mass_source": 12.7},
        {"final_mass_source": 9.5},
        {"final_mass_source": 11.3},
        {"final_mass_source": 13.8}
    ]

def compute_std_dev(events):
    masses = np.array([float(e['final_mass_source']) for e in events])
    mean = np.mean(masses)
    squared_diffs = (masses - mean) ** 2
    variance = squared_diffs.sum() / len(masses)
    return np.sqrt(variance)


def main():
    events = load_gwtc_catalog()
    if not events:
        print('No events found in catalog.')
        sys.exit(0)
    sigma = compute_std_dev(events)
    print(f"Standard deviation of final mass source: {sigma:.3f}")


if __name__ == "__main__":
    main()

import math, random, sys

# Physical constants (SI)
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8         # m·s⁻¹
hbar = 1.054571817e-34   # J·s
k_B = 1.380649e-23       # J·K⁻¹
M_sun = 1.98847e30       # kg

def random_physical_quantity():
    """Return a randomly chosen physical quantity and its value.
    Weighted toward familiar SI units and avoids pathological extremes.
    """
    category = random.choice(['length', 'mass', 'time', 'velocity', 'acceleration', 'energy', 'power'])
    if category == 'length':
        return "meter", random.uniform(0.001, 1000)          # 1–1000 m
    elif category == 'mass':
        return "kilogram", random.uniform(0.001, 1000)        # 0.1–1000 kg
    elif category == 'time':
        return "second", random.uniform(0.001, 1000)         # 0.001–1000 s
    elif category == 'velocity':
        v_mps = random.uniform(0.001, 1000)
        if random.random() < 0.3:
            return "km/s", v_mps * 1e-3
        else:
            return "m/s", v_mps
    elif category == 'acceleration':
        a_mps2 = random.uniform(0.001, 1000)
        if random.random() < 0.2:
            return "m/s²", a_mps2
        else:
            return "g-force", a_mps2 / 9.80665
    elif category == 'energy':
        J = random.uniform(0.001, 1e6)
        if random.random() < 0.3:
            # electron‑volt (dimensionless conversion factor = 1.602e-19)
            return "eV", J * 1.602176634e19
        else:
            return "Joule", J
    elif category == 'power':
        W = random.uniform(0.001, 1e6)
        if random.random() < 0.3:
            return "hp", W / 745.7
        else:
            return "Watt", W


def check_consistency(label, value, unit):
    """Perform a lightweight dimensional consistency check.
    Converts the quantity to SI if necessary and checks against known constants.
    Returns (pass, reason).
    """
    # Convert to SI if unit is a derived prefix or common non‑SI unit
    if unit == "km/s":
        value = value * 1e3
    elif unit == "g-force":
        value = value * 9.80665
    elif unit == "eV":
        value = value * 1.602176634e-19
    elif unit == "hp":
        value = value * 745.7
    # Simple sanity checks against constants
    if label in ["G", "c", "hbar", "k_B", "M_sun"]:
        # Values are already in SI; just verify they match the constants
        return (abs(value - eval(label)) < 1e-12, f"{label} matches constant")
    else:
        # Placeholder: ensure the number is reasonable
        return (abs(value) < 1e9, "value is plausible")


def main():
    print("Random physical quantity and its SI conversion:")
    name, val = random_physical_quantity()
    unit = name
    # Perform check
    passed, reason = check_consistency(name, val, unit)
    print(f"Quantity: {name} ({unit})")
    print(f"Value: {val:.6e}")
    print(f"Check result: {'PASS' if passed else 'FAIL'} - {reason}")

if __name__ == "__main__":
    main()

import numpy as np, json, os, sys, math

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    rs = schwarzschild_radius(M)
    area = 4 * math.pi * rs**2
    l_p2 = planck_length()**2
    return area / (4 * l_p2)

def entropy_to_bits(S):
    # Convert Joules/Kelvin to bits using E = k_B*T*ln(2)
    # S (natural log) -> bits = S / (k_B * ln(2))
    return S / (k_B * math.log(2))

def main():
    M = M_sun  # 1 solar mass
    print(f"Schwarzschild radius of {M/M_sun:.2f} M_sun: {schwarzschild_radius(M):.3e} m")
    T = hawking_temperature(M)
    print(f"Hawking temperature: {T:.3e} K")
    S = bh_entropy(M)
    print(f"Bekenstein‑Hawking entropy: {S:.3e} J/K")
    bits = entropy_to_bits(S)
    print(f"Entropy in bits: {bits:.3e} bits")

if __name__ == "__main__":
    main()

