def random_mass():
    """Return a random mass between 5 and 50 solar masses (kg)."""
    return random.uniform(5.0, 50.0) * M_sun

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c²."""
    return 2.0 * G * M / c**2

def isco_radius_schwarzschild(M):
    """Prograde ISCO for a non‑spinning BH: r_isco = 6 r_s."""
    return 6.0 * schwarzschild_radius(M)

def photon_sphere_radius_schwarzschild(M):
    """Unstable photon sphere at r = 3 r_s."""
    return 3.0 * schwarzschild_radius(M)

def hawking_temperature(M):
    """T_H = ħ c³ / (8π G k_B M)."""
    return hbar * c**3 / (8.0 * math.pi * G * k_B * M)

def planck_length():
    """ℓ_P = sqrt(ħ G / c³)."""
    return math.sqrt(hbar * G) / c**3

def random_spin():
    """Return a dimensionless spin χ in [0, 0.99)."""
    return random.uniform(0.0, 0.99)

def horizon_area_schwarzschild(r_s):
    """A = 4π r_s²."""
    return 4.0 * math.pi * r_s**2

def horizon_area_kerr(M, a):
    """A = 4π (r_+² + a²) where r_+ = GM/c² + sqrt((GM/c²)² - a²)."""
    r_plus = G * M / c**2 + math.sqrt((G * M / c**2)**2 - a**2)
    return 4.0 * math.pi * (r_plus**2 + a**2)

def test_uniformity(num_samples, tol=1e-3):
    failures = 0
    for _ in range(num_samples):
        M = random_mass()
        chi = random_spin()
        # Schwarzschild limit for testing
        a = 0.0
        area = horizon_area_schwarzschild(2.0 * G * M / c**2)
        # Kerr horizon area (identical for a=0)
        area_kerr = horizon_area_kerr(M, a)
        if abs(area - area_kerr) / area > tol:
            failures += 1
            break
    return failures

if __name__ == "__main__":
    samples = 10000
    err = test_uniformity(samples)
    if err == 0:
        print(f"PASS: Horizon area identity holds for {samples} samples.")
