import os, json, math, sys

def load_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        print('FAIL: GWTC_CATALOG_PATH not set')
        sys.exit(1)
    with open(path, 'r') as f:
        return json.load(f)

def compute_radiated_fraction(event):
    m1 = event.get('mass_1_source')
    m2 = event.get('mass_2_source')
    mf = event.get('final_mass_source')
    if None in (m1, m2, mf):
        return None
    total_initial = m1 + m2
    if total_initial == 0:
        return None
    return (total_initial - mf) / total_initial

def main():
    catalog = load_catalog()
    events = catalog.get('events', [])
    fractions = []
    for ev in events:
        eps = compute_radiated_fraction(ev)
        if eps is not None:
            fractions.append(eps)
    if not fractions:
        print('FAIL: No valid events found')
        sys.exit(1)
    max_eps = max(fractions)
    print(f'Max radiated fraction across {len(fractions)} events: {max_eps:.4f}')
    if max_eps <= 0.10:
        print('PASS: All events respect the 10% radiated‑energy bound')
    else:
        print('FAIL: Bound violated (max > 0.10)')

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import math

# Physical constants (SI units)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8         # m s^-1
hbar = 1.054571817e-34   # J s
k_B = 1.380649e-23       # J K^-1
M_sun = 1.98847e30       # kg

def hawking_temperature(M):
    """Hawking temperature T = ħ c³ / (8 π G M k_B)"""
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    """Bekenstein‑Hawking entropy S = k_B * A / (4 l_P²)
    where A = 4π r_s² and r_s = 2GM/c²"""
    r_s = 2 * G * M / c**2
    area = 4 * math.pi * r_s**2
    l_p = planck_length()
    return k_B * area / (4 * l_p**2)

def main():
    masses = {
        "5 M_sun": 5 * M_sun,
        "1e6 M_sun": 1e6 * M_sun,
        "1e12 kg": 1e12
    }

    temps = {}
    entropies = {}
    print("Computed quantities:")
    for label, M in masses.items():
        T = hawking_temperature(M)
        S = bh_entropy(M)
        temps[label] = T
        entropies[label] = S
        print(f"{label:>10}: M = {M:.3e} kg, T = {T:.3e} K, S = {S:.3e} J/K")

    # ---- Consistency checks ----
    # 1. Temperature should decrease monotonically with increasing mass
    sorted_by_mass = sorted(masses.items(), key=lambda kv: kv[1])  # ascending mass
    sorted_temps = [temps[label] for label, _ in sorted_by_mass]
    assert sorted_temps == sorted(sorted_temps, reverse=True), "Temperature does not decrease with mass"

    # 2. Entropy should increase monotonically with mass
    sorted_ents = [entropies[label] for label, _ in sorted_by_mass]
    assert sorted_ents == sorted(sorted_ents), "Entropy does not increase with mass"

    print("\nAll physical consistency checks passed.")
    print("RESULT: PASS")

if __name__ == "__main__":
    try:
        main()
    except AssertionError as e:
        print(f"Consistency check failed: {e}")
        print("RESULT: FAIL")
